mapper.sql:
WHERE sm.facility_id = #{facilityId}
  AND sm.start_at >= #{startAt}
  AND sm.start_at <= #{endAt}
  AND sm.status <> '취소'

mapper.select:
SELECT COUNT(*)
  FROM match_participant mp
  JOIN social_match sm ON sm.match_id = mp.match_id
  JOIN facility f      ON f.facility_id = sm.facility_id
                      AND f.deleted_at IS NULL
  JOIN facility_manager fm ON fm.facility_id = f.facility_id
                          AND fm.user_id = #{managerUserId}
 WHERE sm.facility_id = #{facilityId}
   AND sm.start_at >= #{startAt}
   AND sm.start_at <= #{endAt}
   AND sm.status <> '취소'
   AND mp.participation_status IN ('대기', '확정')
